// Checkout conversion module - ensures paid events are recorded
const fs = require('fs');
const path = require('path');

const PAID_EVENTS_FILE = path.join(__dirname, '..', 'data', 'paid_events.json');

function ensurePaidEventsFile() {
  const dir = path.dirname(PAID_EVENTS_FILE);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  if (!fs.existsSync(PAID_EVENTS_FILE)) {
    fs.writeFileSync(PAID_EVENTS_FILE, JSON.stringify([]));
  }
}

function recordPaidEvent(event) {
  ensurePaidEventsFile();
  const events = JSON.parse(fs.readFileSync(PAID_EVENTS_FILE, 'utf8'));
  events.push({ ...event, timestamp: new Date().toISOString() });
  fs.writeFileSync(PAID_EVENTS_FILE, JSON.stringify(events, null, 2));
  return true;
}

function getPaidEventCount() {
  ensurePaidEventsFile();
  const events = JSON.parse(fs.readFileSync(PAID_EVENTS_FILE, 'utf8'));
  return events.length;
}

module.exports = { recordPaidEvent, getPaidEventCount };
